18	 * was a synchronous no-op, and `.then(...)` below throws on a non-Promise) — but the type itself
19	 * still let a real, explicitly-supplied *synchronous* callback through uncaught: nothing stopped
20	 * a caller from writing `onItemQuantityChange={() => true}`, which reaches the identical
21	 * `TypeError: ...then is not a function` the default-value fix already closed for the omitted
22	 * case. Widened to `boolean | Promise<boolean>` and normalised via `Promise.resolve(...)` so
23	 * either return shape resolves correctly, matching how `662670f8` closed the sibling gap.
24	 *
25	 * `quantity-picker` is not overridden anywhere in this repo (verified by directory listing at
26	 * time of writing), so it stays on the base `@salesforce/retail-react-app/...` path.
27	 */
28	import React from 'react';
29	import { FormattedMessage, useIntl } from 'react-intl';
30	import { Text, VisuallyHidden } from '@salesforce/retail-react-app/app/components/shared/ui';
31	import QuantityPicker from '@salesforce/retail-react-app/app/components/quantity-picker';
32	
33	// See item-variant/index.tsx's own note on why this is `any` rather than a structural type.
34	type SfccProduct = any;
35	
36	type ProductQuantityPickerProps = {
37	  product: SfccProduct;
38	  onItemQuantityChange: (quantity: number) => boolean | Promise<boolean>;
39	  stepQuantity: number;
40	  quantity: number | string;
41	  setQuantity: (quantity: number | string) => void;
42	};
