import React, { type CSSProperties } from 'react';
import {
  Button as ChakraButton,
  IconButton,
  chakra,
  useStyleConfig,
  useMultiStyleConfig,
  type SystemStyleObject,
} from '@chakra-ui/react';
import { ZimmIcon } from '../zimmIcon';
import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';

// All hover/press/focus/disabled interaction states live in zimmButton.css.ts, co-located
// beside this file. ZimmButton is a thin mapping layer: Zimmermann props (inverse,
// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.

type ZimmButtonBaseProps = {
  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
  label: string;
  type?: 'button' | 'submit' | 'reset';
  disabled?: boolean;
  /**
   * Renders the disabled *appearance* while keeping the button focusable and in the Tab
   * order (A10) — HTML `disabled` removes it from the accessibility tree entirely, so screen
   * reader users can never reach it to hear why the action is unavailable. `onClick` is
   * suppressed here rather than by the DOM. Prefer this over `disabled` for
   * unavailable-but-explainable states (e.g. Add to Bag with an out-of-stock size selected).
   *
   * No recipe change is needed: Chakra's `_disabled` pseudo already expands to
   * `&:disabled, &[disabled], &[aria-disabled=true], &[data-disabled]`.
   */
  ariaDisabled?: boolean;
  inverse?: boolean;
  onClick?: () => void;
  style?: CSSProperties;
  /** Chakra `sx` passthrough — for a caller-owned recipe part, not a one-off inline style. */
  sx?: SystemStyleObject;
};

type ZimmLabelButtonProps = ZimmButtonBaseProps & {
  variant?: 'primary' | 'secondary' | 'social';
  /** 'large' = 52px fixed · 'medium' = 40px fixed · 'adaptive' = 40px mobile → 52px desktop
   *  (same responsive size as the social variant, applied to primary/secondary colours). */
  size?: 'large' | 'medium' | 'adaptive';
  fullWidth?: boolean;
  /** Links an explanatory message element by id so screen readers announce it on focus. */
  ariaDescribedBy?: string;
  /** primary/secondary only. Optional icon rendered before the label. Pass a ZimmIcon or any
   *  React node. */
  iconLeading?: React.ReactNode;
  /** primary/secondary only. Optional icon rendered after the label. Pass a ZimmIcon or any
   *  React node. */
  iconTrailing?: React.ReactNode;
  /**
   * variant="social" only — matches ZimmSocialButton's own `icon` prop exactly (same name,
   * same `React.ReactNode` shape), so migrating a `<ZimmSocialButton icon={...} .../>` call
   * site to `<ZimmButton variant="social" icon={...} .../>` needs no prop renaming.
   */
  icon?: React.ReactNode;
  /**
   * variant="social" only — sizes the fixed box `icon`'s SVG is forced to fill
   * (ZimmSocialButton's recipe; Chakra's createIcon renders at 1em×1em by default, so
   * without a fixed box the icon would scale with the button's own responsive font-size
   * instead of staying a constant size). Defaults to 'md' (16px), matching the only size
   * ever confirmed by Figma for the Apple/Google auth buttons. Ignored for every other
   * variant. Reach for this first — only fall back to `iconSx` below when a Figma spec
   * genuinely doesn't match one of sm/md/lg/xl.
   */
  iconSize?: ZimmIconSize;
  /**
   * variant="social" only — escape hatch for the icon box when `iconSize`'s four token
   * values (12/16/20/24px) don't cover a genuinely one-off size. Merges on top of the
   * `iconSize`-resolved box (same `sx`-over-`__css` precedence this file's own top-level
   * `sx` prop already relies on), so e.g. `iconSx={{ width: '18px', height: '18px' }}`
   * overrides just the dimensions without losing the '& svg' fill rule underneath. Prefer
   * `iconSize` whenever the value is one of the four registered sizes — this is for the
   * genuine gap, not a shortcut around the token scale.
   */
  iconSx?: SystemStyleObject;
};

type ZimmIconButtonProps = ZimmButtonBaseProps & {
  variant: 'icon';
  icon: ZimmIconType;
  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
  size?: ZimmIconSize;
};

type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps;

const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';

/** Atom — labelled button (primary/secondary/social) or icon-only button. All visual states
 *  are handled by `zimmButton.css.ts` (co-located beside this file) — no React state for hover/press/focus.
 *  Labelled variants accept optional `iconLeading` and `iconTrailing` nodes rendered either
 *  side of the label; gap between icon and text is set by the button's flex gap in baseStyle. */
export const ZimmButton = (props: ZimmButtonProps) => {
  const { label, type = 'button', disabled = false, ariaDisabled = false, inverse = false, onClick, style, sx } = props;
  // aria-disabled leaves the button clickable at the DOM level, so the no-op has to happen here.
  const handleClick = ariaDisabled ? undefined : onClick;
  const ariaDisabledAttr = ariaDisabled || undefined;
  const labelStyle = useStyleConfig('ZimmButtonLabel', {});
  // Called unconditionally (Rules of Hooks) even though only the variant="social" branch below
  // uses it. 'iconSize' only exists on ZimmLabelButtonProps, not ZimmIconButtonProps, hence the
  // `in` guard. size defaults to 'md' explicitly — see zimmSocialButton/index.tsx's own comment
  // on why this doesn't rely on the recipe's defaultProps.
  const iconSizeProp = 'iconSize' in props ? props.iconSize : undefined;
  const socialStyles = useMultiStyleConfig('ZimmSocialButton', { size: iconSizeProp ?? 'md' });

  if (props.variant === 'icon') {
    return (
      <IconButton
        aria-label={label}
        type={ariaDisabled ? 'button' : type}
        isDisabled={disabled}
        aria-disabled={ariaDisabledAttr}
        onClick={handleClick}
        variant={inverse ? 'iconInverse' : 'icon'}
        size="icon"
        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
        style={style}
        sx={sx}
      />
    );
  }

  const variant = props.variant ?? 'primary';
  const ariaDescribedBy = 'ariaDescribedBy' in props ? props.ariaDescribedBy : undefined;
  // fullWidth defaults to true for variant="social" (ZimmSocialButton was always full-width,
  // Figma-confirmed, no known narrower case) but stays a real, overridable prop — an explicit
  // fullWidth={false} still wins. Every other variant is unchanged: opt-in, default false.
  const fullWidth = props.fullWidth ?? variant === 'social' ? '100%' : undefined;

  if (variant === 'social') {
    return (
      <ChakraButton
        type={ariaDisabled ? 'button' : type}
        isDisabled={disabled}
        aria-disabled={ariaDisabledAttr}
        aria-label={label}
        aria-describedby={ariaDescribedBy}
        onClick={handleClick}
        variant="social"
        size="social"
        width={fullWidth}
        style={style}
        sx={sx}
      >
        {/* Same container>icon+label DOM shape as ZimmSocialButton itself — reused rather than
            reinvented, so this carries over its exact, already-confirmed layout instead of a
            new "should be equivalent" structure. */}
        <chakra.span __css={socialStyles.container}>
          <chakra.span aria-hidden={true} __css={socialStyles.icon} sx={props.iconSx}>
            {props.icon}
          </chakra.span>
          <chakra.span __css={socialStyles.label}>{label}</chakra.span>
        </chakra.span>
      </ChakraButton>
    );
  }

  // size/chakraVariant are only meaningful for primary/secondary from here — the social case
  // already returned above with literal 'social'/'social'.
  const size = props.size === 'adaptive' ? 'social' : props.size === 'medium' ? 'sm' : 'lg';
  // Maps inverse prop to the *Inverse variant suffix defined in zimmButton.css.ts.
  const chakraVariant = `${variant}${inverse ? 'Inverse' : ''}`;

  return (
    <ChakraButton
      type={ariaDisabled ? 'button' : type}
      isDisabled={disabled}
      aria-disabled={ariaDisabledAttr}
      // aria-label makes the accessible name explicit so VoiceOver doesn't read
      // CSS text-transform:uppercase as an acronym (e.g. "A-D-D to bag").
      aria-label={label}
      aria-describedby={ariaDescribedBy}
      onClick={handleClick}
      variant={chakraVariant}
      size={size}
      width={fullWidth}
      style={style}
      sx={sx}
    >
      {props.iconLeading && (
        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
          {props.iconLeading}
        </chakra.span>
      )}
      <chakra.span __css={labelStyle}>{label}</chakra.span>
      {props.iconTrailing && (
        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
          {props.iconTrailing}
        </chakra.span>
      )}
    </ChakraButton>
  );
};

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';

const ZIMM_CART_DRAWER_RECIPE = 'ZimmCartDrawer';

// SFCC-315 builds the drawer shell only — SFCC-277/272 (later commits in this same 18-commit
// plan) will replace this with the real empty-bag component. This placeholder exists only so
// the body isn't blank/broken-looking in the meantime.
const EMPTY_BAG_PLACEHOLDER_TEXT = 'Your bag is empty.';

export type ZimmCartDrawerProps = {
  /** Whether the drawer is open. */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button (all via ZimmDrawer/Chakra's Drawer). */
  onClose: () => void;
  /** Number of line items in the bag. Drives the header title ("BAG • {itemCount}" vs
   *  "YOUR BAG IS EMPTY") and whether `children` or the interim empty-state placeholder renders. */
  itemCount: number;
  /** Element to focus once the drawer finishes closing — see ZimmDrawer's own doc (AC10
   *  focus-return); without this Chakra falls back to focusing document.body. */
  finalFocusRef?: React.RefObject<HTMLElement>;
  /** Cart line items. This organism owns no item-rendering logic itself — the caller supplies
   *  the list (SFCC-270's ProductItem, wired in a later commit in this same plan). Rendered only
   *  while itemCount > 0. */
  children: React.ReactNode;
  /** Reserved slot for SFCC-404's message-aggregation system (validation/error/promo banners).
   *  Always rendered, even with nothing passed — see zimmCartDrawer.css.ts's `messages` part:
   *  the band reserves height regardless, so the drawer doesn't change position when a message
   *  appears or disappears. */
  messages?: React.ReactNode;
  /** Reserved slot for SFCC-275's button group (checkout / continue shopping). Not built in this
   *  commit (SFCC-315 is shell-only) — this organism only provides the slot it will render into
   *  later. */
  footer?: React.ReactNode;
};

/**
 * SFCC-315 — the Cart drawer shell. Wraps ZimmDrawer (size="xLarge") with the cart-specific
 * header title, a height-reserving messages band, a responsive items/totals layout, and a
 * footer slot.
 *
 * Deliberately not wired to a trigger yet — no `_app`/`product-view` changes, no
 * `useCartDrawer` hook, no button-group content, no real empty-state body, no message
 * aggregation. All of those are separate, later commits in this same 18-commit plan — this
 * organism is exercised only via its own Storybook stories today.
 *
 * @param props see ZimmCartDrawerProps
 */
export const ZimmCartDrawer = ({
  isOpen,
  onClose,
  itemCount,
  finalFocusRef,
  children,
  messages,
  footer,
}: ZimmCartDrawerProps) => {
  const styles = useMultiStyleConfig(ZIMM_CART_DRAWER_RECIPE, {});
  const title = itemCount === 0 ? 'YOUR BAG IS EMPTY' : `BAG • ${itemCount}`;

  return (
    <ZimmDrawer isOpen={isOpen} onClose={onClose} size="xLarge" title={title} finalFocusRef={finalFocusRef}>
      <chakra.div __css={styles.messages}>{messages}</chakra.div>
      <chakra.div __css={styles.body}>
        {itemCount === 0 ? <chakra.p textStyle="body2">{EMPTY_BAG_PLACEHOLDER_TEXT}</chakra.p> : children}
      </chakra.div>
      <chakra.div __css={styles.footer}>{footer}</chakra.div>
    </ZimmDrawer>
  );
};

import { breakpoints } from 'app/theme/foundation';
import { DRAWER_HEADER_ROW_HEIGHT } from 'app/theme/components/zimmDrawerShared';

// Figma's actual named drawer sizes (SFCC-898) — five named sizes, not the three/four this
// file previously guessed at. Each name below matches Figma's own naming exactly, so there's
// no re-deriving which number belongs to which concept next time this file is touched:
//
//   Desktop Large — 50%  — Product Details, Filters (desktop width)
//   Tablet        — 80%  — Product Details, Filters (tablet width)
//   Desktop Small — 25%  — Notify Me, Wishlist, Find in Boutique, Regional Storefront,
//                           Cookies, Login
//   X-Large       — 82%  — Cart. SFCC-11: this is the named-size *library* annotation, not a
//                           measurement of the real Cart composition — see `WIDTH_XLARGE` below,
//                           which corrects it a second time against the actual frames.
//   Mobile        — unchanged, the baseStyle treatment every variant collapses to below `md`.
//
// An earlier revision of this file measured 82% off a Figma frame annotated "Tablet = 82% of
// screen" and used it as `small`'s (now `tablet`'s) value — that frame's annotation was wrong
// (or superseded): 82% is actually X-Large's value (Cart), a completely different drawer this
// codebase hasn't built yet, and Tablet is genuinely 80%. Corrected once confirmed directly
// against the list above, not another single frame's own label.
const WIDTH_LARGE = '50%';
const WIDTH_TABLET = '80%';
// The original width set when this drawer shell was first built (2026-08-27) — matches Figma's
// "Desktop Small" exactly. Used by every viewport-independent narrow utility drawer (Find in
// Boutique today; Notify Me/Wishlist/Regional Storefront/Cookies/Login once those exist).
const WIDTH_SMALL = '25%';
// SFCC-11 (Cart build): the "X-Large — 82%" library annotation two paragraphs up is the
// named-size *system* value, not a measurement of the actual Cart composition. Re-measured the
// real frames directly (node 9323:65888 at 1920px, node 9323:65895 at 1440px, file
// QQ427wHWEUjsjP7H8v48Rs) — the cart panel itself (frame "pdp/drawer") is a FIXED 1186px at
// both widths; the backdrop gap grows instead of the panel. 82% of 1920 is 1574px — 388px
// wider than designed. This is the same annotation-vs-measurement trap the comment above
// already records once for Tablet; it recurred here for X-Large. 74.125rem = 1186px.
// Widths/min-widths/max-widths across drawer sizes are a live, unsettled area as of
// 2026-09-17 (Marcel) — this ships to the current measured Figma spec and may be
// reconciled once that broader call is made; not a final word on the sizing model.
// audit-allow: Figma-confirmed fixed width with no --zimm-scale equivalent at this value.
const WIDTH_XLARGE = '74.125rem'; // 1186px

// PDP drawer leaves a strip of backdrop visible below the panel on mobile (SFCC-736 AC 9,
// PO-approved 2026-08-21 — "so a user can easily navigate out"). Re-measured against node
// 40002218:42903 (SFCC-898): overlay 956px tall, panel 898px tall — exactly 58px. Only the
// `mobileGap` variant opts into this; the baseStyle defaults to full-height so utility
// drawers (wishlist auth, etc.) don't need to explicitly override it. No named spacing scale
// step lands on 58px — provisional raw value pending a foundation token.
const MOBILE_BOTTOM_GAP = '3.625rem'; // 58px

// Close-button inset, measured from the pdp/drawer header frames. `tablet`/`small`/`xLarge`/
// `mobile` all share the same measured inset (32px/40px) at every width — only `large` switches
// to the wider 48px/64px inset, at/above the tablet breakpoint. Below that breakpoint `large`'s
// own override doesn't apply either, and the baseStyle inset is used instead, which is also how
// the whole drawer collapses to the mobile treatment on a narrow viewport regardless of `size`.
const INSET_COMPACT = { top: 'var(--zimm-scale-3xl)', right: 'var(--zimm-scale-2xl)' };
const INSET_LARGE = { top: 'var(--zimm-scale-1200)', right: 'var(--zimm-scale-4xl)' };

// Header constants — from Figma drawer/header frame measurements.
// Compact horizontal inset (small/mobile): px=32px. Large desktop: px=64px.
// Small desktop header uses py=24px. Large desktop: container height=120px (row centred).
// Mobile base: container height=72px.
const HEADER_PADDING_COMPACT_X = 'var(--zimm-scale-2xl)'; // 32px
const HEADER_PADDING_LARGE_X = 'var(--zimm-scale-4xl)'; // 64px
const HEADER_PADDING_Y = 'var(--zimm-scale-xl)'; // 24px — small desktop py
// audit-allow: Figma-confirmed container heights with no --zimm-scale equivalents at these values.
const HEADER_HEIGHT_LARGE = '120px';
const HEADER_HEIGHT_MOBILE = '72px';

export const ZimmDrawer = {
  parts: ['overlay', 'content', 'closeButton', 'header', 'headerTitle'],
  baseStyle: {
    // Explicit position/inset rather than relying on Chakra's own built-in `Drawer` overlay
    // styling — confirmed via inspection that it doesn't apply (renders `position: static`,
    // zero size) when the `<Drawer>` isn't given Chakra's own `size` prop, which this component
    // deliberately omits (see maxWidth note below). Owning it here avoids depending on that.
    overlay: {
      position: 'fixed',
      inset: 0,
      background: 'var(--zimm-color-opacity-50)',
      zIndex: 'overlay',
    },
    content: {
      // Chakra's own <DrawerContent> baked in a default white background
      // (@chakra-ui/theme's modal.js `baseStyleDialog`: `bg: colors.white`) that this recipe
      // never needed to set itself while that component was still in use — now that
      // ZimmDrawer hand-rolls its own content element (see index.tsx's file-level comment),
      // nothing supplies one unless it's set here. Matches Figma's pdp/drawer panel background
      // (bg-[var(--brand/color/palette/white,white)]) — --zimm-color-bg-07 resolves to the
      // same grey.white value (SFCC-898 — the panel briefly had no background at all).
      background: 'var(--zimm-color-bg-07)',
      width: '100%',
      // Matches `width` at every step below — Chakra's own `Drawer` theme defaults to
      // `size="xs"` (maxW 20rem) when no `size` prop is passed to `<Drawer>` (deliberate: its
      // fixed size scale has no 50%/25% steps), and that default `maxW` otherwise still caps
      // our own `width` override since we never reset it.
      maxWidth: '100%',
      // A `height` reduction, not a `bottom` offset — Chakra's own Slide transition (see
      // @chakra-ui/transition's slide.js `placement: 'right'` case) pins the sliding wrapper
      // with `position: fixed; top: 0; right: 0; bottom: 0`, a definite height. `bottom` on
      // this `position: relative` DrawerContent just shifts the box within that instead of
      // reliably opening a gap (SFCC-898 — mobile bottom gap wasn't rendering at all); a
      // percentage `height` resolves cleanly against that definite-height ancestor instead.
      // CodeRabbit (PR review): baseStyle should default to full-height so utility drawers
      // don't inherit the PDP-specific 58px backdrop strip — moved to the `mobile` variant.
      height: '100%',
      // Header stays fixed; only the content area (ZimmPdpDrawer's own `content` part) scrolls —
      // AC 10, "content area scrolls independently without the tab header scrolling".
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden',
    },
    // Was missing `position: absolute` since this component's original commit — the
    // top/right insets below were silently no-ops (closeButton rendered as a normal in-flow
    // block instead of overlaying the header's corner), which is the root cause of SFCC-898's
    // close-button-misaligned-with-tabs defect across every breakpoint.
    //
    // height/display/alignItems/justifyContent: matches zimmTabs.css.ts's `menu.minHeight`
    // (DRAWER_HEADER_ROW_HEIGHT, zimmDrawerShared.ts) and centers the icon inside it — the
    // close icon's own intrinsic size doesn't equal the tab row's real rendered height, so
    // matching only `top` between the two (as before) left their vertical centers slightly
    // offset (SFCC-898, mobile). Only applies to the floating close button (no `title` passed) —
    // the inline title-row close button below is a normal flex child, not absolutely positioned.
    closeButton: {
      position: 'absolute',
      ...INSET_COMPACT,
      height: DRAWER_HEADER_ROW_HEIGHT,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    },
    // Drawer header — title (flex-1, left) + close button (right).
    // baseStyle applies the mobile/compact treatment: px=32px, container h=72px centred.
    // SFCC-926 (Figma): paddingBlock is 0 at mobile so the 72px minHeight controls the height
    // (flex centering handles vertical alignment). At md+ 24px block padding applies — matching
    // Figma's "small desktop py" spec without overriding the mobile 72px container height.
    header: {
      display: 'flex',
      alignItems: 'center',
      gap: 'var(--zimm-scale-xs)',
      backgroundColor: 'var(--zimm-color-text-inverse)',
      paddingInline: HEADER_PADDING_COMPACT_X,
      paddingBlock: 0,
      minHeight: HEADER_HEIGHT_MOBILE,
      flexShrink: 0,
      [`@media (min-width: ${breakpoints.md})`]: {
        paddingBlock: HEADER_PADDING_Y,
      },
    },
    headerTitle: {
      display: 'flex',
      height: 'var(--zimm-scale-3xl)',
      alignItems: 'center',
      flex: '1 0 0',
      minWidth: 0,
      overflow: 'hidden',
      whiteSpace: 'nowrap',
      color: 'var(--zimm-color-text-default)',
    },
  },
  variants: {
    large: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_LARGE,
          maxWidth: WIDTH_LARGE,
          height: '100%',
        },
      },
      closeButton: {
        [`@media (min-width: ${breakpoints.md})`]: INSET_LARGE,
      },
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          paddingInline: HEADER_PADDING_LARGE_X,
          minHeight: HEADER_HEIGHT_LARGE,
        },
      },
    },
    // Figma's "Tablet" size — the tablet-range step for Product Details/Filters, which
    // graduates to `large` (Desktop Large) at the desktop breakpoint via the caller's own
    // useBreakpointValue (ZimmPdpDrawer never selects this variant itself).
    tablet: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_TABLET,
          maxWidth: WIDTH_TABLET,
          height: '100%',
        },
      },
    },
    // Figma's "Desktop Small" — always narrow, at every width above the mobile collapse. No
    // js-level graduation to another variant the way `tablet` graduates to `large` — this is
    // the whole point for its utility-drawer consumers (Find in Boutique today).
    small: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_SMALL,
          maxWidth: WIDTH_SMALL,
          height: '100%',
        },
      },
    },
    // Figma's "X-Large" (Cart) — not consumed anywhere yet (Cart is a full page today, not a
    // drawer), but the real value is already here under the right name for when that changes.
    // `maxWidth: '100%'` (not WIDTH_XLARGE) so a viewport narrower than 1186px but still ≥ `md`
    // doesn't overflow.
    xLarge: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_XLARGE,
          maxWidth: '100%',
          height: '100%',
        },
      },
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          minHeight: 'unset',
          paddingBlock: HEADER_PADDING_Y,
        },
      },
    },
    // CodeRabbit (PR review): 58px backdrop strip is PDP-specific (SFCC-736 AC 9, PO-approved)
    // and must not apply to utility drawers — scoped here to the explicit `mobile` variant.
    // Figma's "Mobile" size — only drawers that need the strip opt in; utility drawers
    // (wishlist auth, etc.) use `large` instead, which collapses to full-height via baseStyle.
    mobile: {
      content: {
        height: `calc(100% - ${MOBILE_BOTTOM_GAP})`,
      },
    },
  },
};

